window.STUDY_DATA.questions.push({"id":"img-ee-01","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"欧姆定律","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"如下图电路，已知 U=12V，R=4Ω，求电流 I。<br><svg width='200' height='100' xmlns='http://www.w3.org/2000/svg'><rect width='200' height='100' fill='#fafafa'/><line x1='30' y1='50' x2='60' y2='50' stroke='#333' stroke-width='2'/><rect x='60' y='35' width='40' height='30' fill='none' stroke='#333' stroke-width='2'/><text x='68' y='55' font-size='12'>R</text><line x1='100' y1='50' x2='140' y2='50' stroke='#333' stroke-width='2'/><circle cx='155' cy='50' r='15' fill='none' stroke='#333' stroke-width='2'/><text x='148' y='55' font-size='12'>U</text><line x1='170' y1='50' x2='180' y2='50' stroke='#333' stroke-width='2'/><line x1='180' y1='50' x2='180' y2='80' stroke='#333' stroke-width='2'/><line x1='180' y1='80' x2='30' y2='80' stroke='#333' stroke-width='2'/><line x1='30' y1='80' x2='30' y2='50' stroke='#333' stroke-width='2'/></svg>","options":["3A","4A","8A","48A"],"answer":"3A","analysis":"【审题】U=12V、R=4Ω，求 I。与其余图片题（串联分压、并联总电流、二极管电流）同组，考读图后套基本公式。【定律/公式】I=U/R；U=IR；P=UI=I²R。【分步推导】① 12÷4=3A。② 反算 3④=12V。③ 功率 36W 双式一致。④ 其余选项均非电流量。【答案】3A（选项 A）。【易错】把电阻当电流；加减误用；相乘；除法反向。","tags":["带图","欧姆定律"],"source":"带图题","score":5,"steps":["【秒懂考点】I=U/R=12÷4=3A","【第一步：认准公式】已知电压与电阻求电流，直接用 I=U/R","【第二步：代入】12÷4=3A。电压是电阻的 3 倍，所以电流为 3A，量级合理","【第三步：反算验算】U=IR=3×4=12V 与题给一致；功率 P=UI=12×3=36W，与 I²R=9×4=36W 吻合","【第四步：排除干扰项】4A 是直接取了电阻数值；8A 是 12−4；48A 是 12×4，三者都不是电流","【答案】3A（A）"],"pitfalls":["选 4A：把电阻数值当电流","选 8A：把 U−R 当结果","选 48A：把 U×R 相乘，量纲不对","除法方向反：4÷12≈0.33A，不在选项但在计算时仍要防"]});

window.STUDY_DATA.questions.push({"id":"img-ee-02","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"串联电路","type":"single","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"两个电阻 R₁=6Ω、R₂=3Ω 串联接在 9V 电源上，求 R₁ 两端电压。<br><svg width='220' height='100' xmlns='http://www.w3.org/2000/svg'><rect width='220' height='100' fill='#fafafa'/><line x1='20' y1='50' x2='45' y2='50' stroke='#333' stroke-width='2'/><rect x='45' y='35' width='35' height='30' fill='none' stroke='#333' stroke-width='2'/><text x='50' y='55' font-size='11'>R₁</text><line x1='80' y1='50' x2='105' y2='50' stroke='#333' stroke-width='2'/><rect x='105' y='35' width='35' height='30' fill='none' stroke='#333' stroke-width='2'/><text x='110' y='55' font-size='11'>R₂</text><line x1='140' y1='50' x2='170' y2='50' stroke='#333' stroke-width='2'/><circle cx='185' cy='50' r='14' fill='none' stroke='#333' stroke-width='2'/><text x='178' y='55' font-size='11'>9V</text><line x1='199' y1='50' x2='200' y2='50' stroke='#333' stroke-width='2'/><line x1='200' y1='50' x2='200' y2='80' stroke='#333' stroke-width='2'/><line x1='200' y1='80' x2='20' y2='80' stroke='#333' stroke-width='2'/><line x1='20' y1='80' x2='20' y2='50' stroke='#333' stroke-width='2'/></svg>","options":["3V","6V","9V","1.5V"],"answer":"6V","analysis":"【审题】R₁=6Ω、R₂=3Ω 串联接 9V，求 R₁ 两端电压。与\"并联求总电流\"那道成对，考串联分压。【定律/公式】串联：I 相同；U₁/U₂=R1/R2；U₁=R1/(R1+R2)·U；R总=R1+R2。【分步推导】① R总=9Ω，I=1A。② U₁=1⑥=6V。③ 分压公式复核：6/9⑨=6V。④ KVL 校验：6+3=9V。【答案】6V（选项 B）。【易错】与另一电阻电压混淆；以为各承受全压；比例算反；用并联思路。","tags":["带图","串联分压"],"source":"带图题","score":6,"steps":["【秒懂考点】串联分压：U₁=9×6/(6+3)=9×6/9=6V","【第一步：串联电流相同】R₁、R₂ 串联，通过同一电流 I=U/(R1+R2)=9/9=1A","【第二步：用分压公式快算】串联电压与电阻成正比：U₁=R1/(R1+R2)×U=6/9×9=6V。电阻大的分得电压多，R₁=6Ω 比 R₂=3Ω 大，所以 U₁ 更大","【第三步：逐个验算】U₁=IR1=1×6=6V，U₂=1×3=3V，两者相加 9V，等于电源电压，KVL 成立","【第四步：排除干扰项】3V 是 R₂ 的电压（分给了另一边）；9V 是把电源电压全给 R₁；1.5V 是把分压比算反","【答案】6V（B）"],"pitfalls":["选 3V：把 U₁ 与 U₂ 的位置搞反，分压按电阻正比，大电阻分得大电压","选 9V：以为串联后每个电阻都承受全电压","选 1.5V：把分压比写成 3/9 的一半或其他错误比例","用并联公式算：串联不能按电压相等处理"]});

window.STUDY_DATA.questions.push({"id":"img-ee-03","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-2","knowledgePoint":"并联电路","type":"single","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"R₁=6Ω、R₂=3Ω 并联接在 12V 电源上，求总电流。<br><svg width='200' height='120' xmlns='http://www.w3.org/2000/svg'><rect width='200' height='120' fill='#fafafa'/><line x1='30' y1='30' x2='30' y2='90' stroke='#333' stroke-width='2'/><line x1='30' y1='30' x2='80' y2='30' stroke='#333' stroke-width='2'/><rect x='80' y='18' width='35' height='25' fill='none' stroke='#333' stroke-width='2'/><text x='85' y='35' font-size='11'>R₁</text><line x1='115' y1='30' x2='160' y2='30' stroke='#333' stroke-width='2'/><line x1='30' y1='90' x2='80' y2='90' stroke='#333' stroke-width='2'/><rect x='80' y='78' width='35' height='25' fill='none' stroke='#333' stroke-width='2'/><text x='85' y='95' font-size='11'>R₂</text><line x1='115' y1='90' x2='160' y2='90' stroke='#333' stroke-width='2'/><line x1='160' y1='30' x2='160' y2='90' stroke='#333' stroke-width='2'/><circle cx='175' cy='60' r='14' fill='none' stroke='#333' stroke-width='2'/><text x='168' y='65' font-size='10'>12V</text></svg>","options":["2A","4A","6A","1.5A"],"answer":"6A","analysis":"【审题】R₁=6Ω、R₂=3Ω 并联接 12V，求总电流。与串联分压那道成对，与\"并联求支路电流\"的应用题同考点。【定律/公式】并联：I=I₁+I₂；Ii=U/Ri；R=R1R2/(R1+R2)；I₁/I₂=R2/R1。【分步推导】① I₁=2A、I₂=4A。② 总 6A。③ 校验：R=18/9=2Ω，12/2=6A。④ 故答 6A。【答案】6A（选项 C）。【易错】只算一支；用分压思路；并联当串联；加法粗心。","tags":["带图","并联"],"source":"带图题","score":6,"steps":["【秒懂考点】并联电压相同，各支路电流 I₁=12/6=2A、I₂=12/3=4A，总电流 6A","【第一步：并联电压相等】两电阻都接在 12V 两端，每条支路电压都是 12V，不需要分压","【第二步：算支路电流】I₁=12÷6=2A，I₂=12÷3=4A。电阻小的支路电流大（3Ω 那条 4A），符合反比分流","【第三步：求总电流】I=I₁+I₂=2+4=6A。也可用等效电阻 R=6×3/9=2Ω，再算 12÷2=6A，两法一致","【第四步：排除干扰项】2A 或 4A 都是单条支路电流；1.5A 是把 12 除以总电阻算错","【答案】6A（C）"],"pitfalls":["只算一条支路就作答：总电流必须两路相加","用串联分压算电压：并联电压相同，不需分压","等效电阻算成 9Ω：把并联当串联（6+3）","把 2A 与 4A 相加错成 5A：加法粗心"]});

window.STUDY_DATA.questions.push({"id":"img-ee-04","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-5","knowledgePoint":"二极管","type":"single","typeLabel":"单选","difficulty":2,"difficultyLabel":"强化","stem":"理想二极管电路，电源 U=5V，R=1kΩ，求电流 I。<br><svg width='220' height='100' xmlns='http://www.w3.org/2000/svg'><rect width='220' height='100' fill='#fafafa'/><line x1='20' y1='50' x2='50' y2='50' stroke='#333' stroke-width='2'/><rect x='50' y='35' width='30' height='30' fill='none' stroke='#333' stroke-width='2'/><text x='55' y='55' font-size='10'>R</text><line x1='80' y1='50' x2='100' y2='50' stroke='#333' stroke-width='2'/><polygon points='100,35 100,65 120,50' fill='none' stroke='#333' stroke-width='2'/><line x1='120' y1='35' x2='120' y2='65' stroke='#333' stroke-width='2'/><text x='102' y='30' font-size='10'>D</text><line x1='120' y1='50' x2='160' y2='50' stroke='#333' stroke-width='2'/><circle cx='175' cy='50' r='14' fill='none' stroke='#333' stroke-width='2'/><text x='168' y='55' font-size='10'>5V</text><line x1='189' y1='50' x2='200' y2='50' stroke='#333' stroke-width='2'/><line x1='200' y1='50' x2='200' y2='80' stroke='#333' stroke-width='2'/><line x1='200' y1='80' x2='20' y2='80' stroke='#333' stroke-width='2'/><line x1='20' y1='80' x2='20' y2='50' stroke='#333' stroke-width='2'/></svg>","options":["5mA","0mA","2.5mA","10mA"],"answer":"5mA","analysis":"【审题】理想二极管电路，U=5V、R=1kΩ，求 I。考理想二极管模型与限流计算。【定律/公式】理想二极管：正偏压降 0V，反偏电流 0；实际硅管 0.7V、锗管 0.3V。I=(U−VF)/R。【分步推导】① 判正偏。② 理想模型 VF=0 → I=5/1k=5mA。③ 若实际硅管：I=(5−0.7)/1k=4.3mA。④ 故理想情形答 5mA。【答案】5mA（选项 A）。【易错】方向判反；理想与实际混用；kΩ 不换算；与反偏情形混淆。","tags":["带图","二极管"],"source":"带图题","score":7,"steps":["【秒懂考点】理想二极管正向导通压降为 0，I=U/R=5÷1k=5mA","【第一步：先判二极管状态】电源正端经二极管接电阻，二极管正向偏置，理想模型下导通，压降取 0V","【第二步：算电流】二极管导通后相当于导线，全部 5V 落在 R 上：I=5V÷1kΩ=5mA","【第三步：若按实际硅管算】压降 0.7V，则 I=(5−0.7)/1k=4.3mA。本题明确\"理想二极管\"，所以用 5mA","【第四步：排除干扰项】0mA 是把二极管当截止（反接才会）；2.5mA 是凭空取半；10mA 是把 5V 除以 0.5kΩ","【答案】5mA（A）"],"pitfalls":["选 0mA：把正偏当反偏，方向判断错","实际管也算 5mA：硅管有 0.7V 压降，应得 4.3mA，题目说\"理想\"才可取 5mA","单位不统一：1kΩ 直接当 1Ω 会算成 5A","把二极管反向电阻当正向：反偏时电流几乎为零，与本题情形不同"]});

window.STUDY_DATA.questions.push({"id":"img-ee-05","module":"major","subject":"电工电子技术基础","chapter":"ch-ee-4","knowledgePoint":"基尔霍夫电流定律","type":"single","typeLabel":"单选","difficulty":3,"difficultyLabel":"强化","stem":"节点处三条支路电流：I₁=3A 流入，I₂=2A 流入，求 I₃。<br><svg width='180' height='120' xmlns='http://www.w3.org/2000/svg'><rect width='180' height='120' fill='#fafafa'/><circle cx='90' cy='60' r='5' fill='#333'/><line x1='20' y1='30' x2='85' y2='55' stroke='#333' stroke-width='2'/><polygon points='60,42 70,48 62,52' fill='#333'/><text x='25' y='28' font-size='11'>I₁=3A↓</text><line x1='20' y1='90' x2='85' y2='65' stroke='#333' stroke-width='2'/><polygon points='60,78 70,72 62,68' fill='#333'/><text x='25' y='105' font-size='11'>I₂=2A↓</text><line x1='95' y1='60' x2='160' y2='60' stroke='#333' stroke-width='2'/><polygon points='130,55 140,60 130,65' fill='#333'/><text x='120' y='50' font-size='11'>I₃=?</text></svg>","options":["1A 流出","5A 流出","1A 流入","5A 流入"],"answer":"5A 流出","analysis":"【审题】节点三条支路 I₁=3A 流入、I₂=2A 流入，求 I₃。考 KCL 的最简应用（两条同向流入）。【定律/公式】KCL：ΣI入=ΣI出；或 ΣI=0（流入正、流出负）。I₃ 的大小等于其余支路代数和，方向取相反以平衡。【分步推导】① 流入合计 3+2=5A。② 必有 5A 流出。③ 故 I₃=5A 流出。④ 验算 5=5。【答案】5A 流出（选项 B）。【易错】同向相减；方向答反；随意标方向；不验算。","tags":["带图","KCL"],"source":"带图题","score":7,"steps":["【秒懂考点】两条支路都流入 3A 和 2A，按 KCL 第三条必须流出 5A","【第一步：先看方向】题给 I₁=3A 流入、I₂=2A 流入，两条都是流入，总流入 5A","【第二步：列 KCL】流入之和等于流出之和：3+2=I₃，故 I₃=5A。既然要平衡 5A 的流入，第三条支路只能是流出 5A","【第三步：排除干扰项】\"1A 流出\"是把 3−2 当结果；\"1A 流入\"是减法加错方向；\"5A 流入\"是把方向搞反（三条都流入就无法平衡）","【第四步：自查】流入 5A、流出 5A，节点电荷收支平衡，方程自洽","【答案】5A 流出（B）"],"pitfalls":["选\"1A 流出\"：把两条流入相减，KCL 是相加不是相减","选\"5A 流入\"：方向反了，若三条都流入则电荷无从流出","把方向当作可以随便标：方向错会直接导致答案错","不做收支自查：流入总和与流出总和必须相等"]});

